   34:     time_t LocalTime(int year, int month, int day, int hour, int minute, int second)
   35:     {
   36:         std::tm t{};
   37:         t.tm_year = year - 1900;
   38:         t.tm_mon = month - 1;
   39:         t.tm_mday = day;
   40:         t.tm_hour = hour;
   41:         t.tm_min = minute;
   42:         t.tm_sec = second;
   43:         t.tm_isdst = -1;
   44:         return mktime(&t);
