   47:     bool IsLocalMidnightOn(time_t when, int year, int month, int day)
   48:     {
   49:         const std::tm t = safe_localtime(when);
   50:         return t.tm_year == year - 1900 && t.tm_mon == month - 1 && t.tm_mday == day
   51:             && t.tm_hour == 0 && t.tm_min == 0 && t.tm_sec == 0;
   52:     }
   53: 
   54:     /// Ticks the reset over [from, to) the way World::Update does; the next reset is computed from computeNow(tick).
   55:     template<class ComputeNow>
   56:     int CountFirings(time_t& stored, time_t from, time_t to, ComputeNow computeNow)
   57:     {
   58:         int firings = 0;
   59:         for (time_t tick = from; tick < to; ++tick)
   60:         {
   61:             if (tick > stored)
   62:             {
   63:                 ++firings;
   64:                 stored = NextMonthlyQuestReset(computeNow(tick), stored, false);
   65:             }
   66:         }
   67:         return firings;
   68:     }
   69: }
