   77:         { 2026,  1,  1,  0,  0,  0, 2026, 2 },   // exactly a reset
   78:         { 2026,  2, 28, 23, 59, 59, 2026, 3 },   // February, common year
   79:         { 2028,  2, 29, 12,  0,  0, 2028, 3 },   // February, leap year
   80:         { 2028,  2,  1,  0,  0,  1, 2028, 3 },
   81:         { 2026, 12, 31, 23, 59, 59, 2027, 1 },   // year end
   82:         { 2027, 12,  1,  0,  0,  0, 2028, 1 },
   83:         { 2026,  6, 30, 23, 59, 59, 2026, 7 },
   84:         { 2027,  7, 15,  6, 30,  0, 2027, 8 },
